/**
 * The types `save/coin-bonus/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    TotalCoinBonusSaveExtract
 * depends    src/mechanics/coin-bonus/types
 * used by    src/save/coin-bonus/index, src/save/coin-bonus/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { TotalCoinBonusBreakdown, TotalCoinBonusInput } from '../../mechanics/coin-bonus/types'

/** A save's Total Coin Bonus at one tier: what was read, what it multiplies to, and what was not. */
export interface TotalCoinBonusSaveExtract {
  /** Everything read from the save, in the shape `computeTotalCoinBonus` takes. */
  input: TotalCoinBonusInput
  /** Each row of the game's All Coins Bonuses panel, and the total. */
  bonus: TotalCoinBonusBreakdown
  /** What the save could not answer, and what was assumed in its place. */
  warnings: string[]
}
